	// Note that StateSnapshot typically satisfies pr.Match < lastIndex, but
	// `pr.Paused()` is always true for StateSnapshot, so sendAppend is a
	// no-op.
	if pr.Match < r.raftLog.lastIndex() || pr.State == tracker.StateProbe {
		r.sendAppend(m.From)
